INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('1','28/09','02/10','乾','Qián','Ciel','Force créative','Fermeté','Fermeté','C''est l''activité. Créer. Activation de l''énergie dynamique. C''est l''effort. Réalisation initiative. Déploiement des qualités Yang','["━━━━━", "━━━━━", "━━━━━", "━━━━━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('2','13/02','18/02','坤','Kūn','Terre','Réceptivité','Souplesse','Souplesse','C''est la matérialisation. Réceptivité. Disponibilité. Adaptation. Accomplissement. Déploiement des qualités Yin','["━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('3','02/03','07/03','屯','Zhūn','Difficulté','Persévérance','Patience','Rester stable ds la difficulté','C''est commencer dans la confusion. Hiérarchiser les priorités. Résoudre les premières difficultés. Défrichage. Il est bon de se faire aider. Favoriser toutes les énergies qui vont générer le progrès. Déterminer une direction.','["━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('4','10/11','15/11','蒙','Méng','Innocence','Apprentissage','Humilité','Apprentissage pour mettre en ordre, adopter règles yang','C''est apprendre et à transmettre. Manque de maturité. Il faut agir sans réfléchir. Épanouir des capacités naissantes. Le danger est dans l''immobilisme et l''interrogation. Recevoir ce qui ne vieillit pas','["━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('5','17/07','22/07','需','Xū','Attente','Attente active','Confiance','Ne pas m''engager - attendre le temps de l''action','C''est apprendre à différer. Ne pas chercher à faire progresser l''action. Vivre sur ses réserves. Alimenter l''attente par un apport enrichissant pour se renforcer. Savoir patienter.','["━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('6','08/10','12/10','讼','Sòng','Conflit','Contournement','Modération','Pas d''affectivité - désamorcer le conflit potentiel','C''est sortir d''une controverse. Nécessité de plaider sa cause devant des contradicteurs. Intervenir dans le règlement d''un conflit, même interne, pour empêcher son développement. Se justifier. Prendre position. Souplesse','["━━━━━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('7','16/11','21/11','师','Shī','Armée','Organisation','Discipline','Vaincre le souci - organiser la masse confuse','C''est la mobilisation devant un péril. Épreuve de force. Moment pénible. Mettre de l''ordre dans une masse confuse. Se discipliner. Lutter contre un envahissement. Harmoniser ses contradictions internes.','["━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('8','02/02','06/02','⽐','Bǐ','Solidarité','Alliance','Sincérité','La joie que les choses se réunissent - échange, entraide, réintégrer le Yin','C''est solidariser. Créer un esprit de corps autour d''un centre. Faire adhérer à un but commun. Rassembler. Harmoniser. Être en accord. Chercher ou accepter l''union. Urgence à coopérer avant qu''il ne soit trop tard.','["━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('9','23/07','28/07','⼩','Xiǎo Chù','Modération','Contention','Douceur','Manque à combler - développer le yin','C''est apprivoiser de manière yin le temps et les difficultés. Résistance passive. Voir ce qui est en germe et qui va se développer. Pas d''initiative. Accomplir de petites choses pour en bâtir de grandes.','["━━━━━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('10','02/07','06/07','履','Lǚ','Conduite','Progression','Prudence','Ne pas se figer - respect en souplesse - approche du fort par le faible','C''est se conduire avec prudence au contact d''une force puissante. Situation explosive et périlleuse. Respecter ou faire respecter les règles. Veiller à leur application pour assurer la bonne marche des événements.','["━━━━━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('11','07/07','11/07','泰','Tài','Paix','Harmonisation','Ouverture','Rechercher harmonie et équilibre - agir au bon endroit','C''est harmoniser. La floraison. L''expansion. Le courant porteur. Communiquer. Se relier. Rechercher et maintenir l''équilibre et l''harmonie. Suivre la profusion naturelle du moment.','["━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('12','06/01','10/01','否','Pǐ','Déclin','Préservation','Retrait','Rechercher harmonie et équilibre - ne pas agir, se retirer','C''est la récession. L''absence d''harmonie. Le flétrissement. Toute communication est bloquée. Aucune alliance n''est possible. Courant néfaste. Ne pas attirer l''attention. Garder ses forces pour le renouveau.','["━━━━━", "━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('13','15/05','20/05','同','Tóng Rén','Union','Coopération','Ouverture','Laisser son cœur s''ouvrir - organiser, entreprendre','C''est aller vers l''autre. Identifier. Reconnaître les différences. Accepter. S''enrichir des différences externes. L''intérêt particulier est aussi l''intérêt commun. Tous les éléments sont liés entre eux.','["━━━━━", "━━━━━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('14','04/08','10/08','⼤','Dà Yǒu','Possession','Gestion','Générosité','Faire advenir - grand pouvoir de réalisation','C''est réaliser. Rendre réel. Permettre à chacun de donner son maximum d''énergie créatrice. Essayer d''être bénéficiaire du grand avoir. Éviter tout ce qui peut le compromettre. Seul celui qui maîtrisera les éléments du grand avoir pourra le réaliser.','["━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('15','01/01','05/01','谦','Qiān','Humilité','Effacement','Modestie','Être léger - légèreté simplicité - champ d''intervention limité','C''est se tenir en souplesse et avec simplicité devant une agression. Concentrer sa force intérieure. Éviter les complications. Chercher les solutions les plus simples. Ne pas s''engager sur une voie avec des obstacles. S''affirmer face à l''extérieur.','["━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
