INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('17','25/03','29/03','随','Suí','Suivi','Adaptation','Souplesse','Être sans intention - s''insérer dans un courant','C''est suivre et s''insérer avec aisance dans un courant porteur. L''action doit être minimum. Guider ou être guidé. Une voie nouvelle peut apparaître. Ne pas résister. Aller à la suite de quelqu''un ou de quelque chose.','["━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
