INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('19','21/05','26/05','临','Lín','Approche','Avancée','Bienveillance','S''associer - s''entraider - être prudent','C''est favoriser sereinement la croissance de ce qui est en train de monter en puissance. Accueillir ce qui vient. Voir loin. Veiller à tout ce qui peut provoquer un trouble. Surveiller ses arrières. Point de rencontre.','["━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('20','27/01','01/02','观','Guān','Contemplation','Observation','Lucidité','Prendre du recul - préparation avant l''action','C''est regarder en face et élever son point de vue. Être prévoyant. Penser aux conséquences futures de l''action. Laisser les choses émerger. En deviner le sens. On observe. On est observé. Changer sa manière de voir les choses.','["━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('21','20/03','24/03','噬','Shì Kè','Morsure','Coupure','Détermination','Agir (on n''a plus le choix) vite et avec fermeté','C''est trancher. Rétablir l''harmonie avec fermeté. Faire face aux problèmes. Affronter résolument et vigoureusement l''obstacle. Refuser la réalité apporte des conséquences brutales.','["━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('22','10/04','14/04','贲','B','lgence','Ornementation','Mesure','Harmoniser l''interne et l''externe - agir avec souplesse','C''est prendre soin de l''apparence. Ajuster le fond et la forme.','[" ━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('23','07/02','12/02','剥','Bō','Éclatement','Lâcher prise','Acceptation','Gérer le dépouillement - ne pas entreprendre','C''est tenir dans la durée. S''économiser. Lutter contre l''usure de la situation. Faire voler en éclats les vieilles habitudes. Point d''usure extrême. Vigilance. Retour en arrière impossible. Prévoir les suites.','["━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('24','19/02','24/02','复','Fù','Retour','Renaissance','Espérance','S''examiner et réfléchir - ne rien précipiter, agir avec prudence','C''est revenir à la source pour recommencer. Accompagner le renouveau. Retournement de situation dans un sens favorable. Une nouvelle voie se dessine. Attention à ne pas gâcher cette chance. Veiller à ne pas forcer le mouvement.','["━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('25','30/03','04/04','⽆','Wú Wàng','Vérité','Action juste','Spontanéité','Gérer l''inattendu - favorable dans l''ouverture','C''est réagir spontanément sans plans préconçus en fonction des circonstances. Écouter son intuition. Libérer son esprit. Agir sans calcul à l''écoute de l''instant. Sans préméditation. Rien ne sera positif en dehors de cette voie.','["━━━━━", "━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('26','12/07 -16/07','','⼤','Dà Chù','Maîtrise','Accumulation','Patience','Choisir le moment juste - engagement, persévérance','C''est apprivoiser l''action de manière Yang. Avec fermeté. Rester concentré. Il n''est pas possible de s''opposer à la force, ni de l''affronter. Rechercher dans le passé ce qui reproduit les schémas anciens. Action subtile. Donner une orientation.','["━━━━━", "━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('27','25/02','01/03','颐','Yí','Nourriture','Nutrition','Soin','Entretenir l''existence - observer une juste mesure','C''est réguler la situation. Nourrir au quotidien la situation et ses acteurs. Trouver une diététique de vie qui passe par l''attention au corps. Assimiler ce qui a précédé. Faire des choix sélectifs. Durer.','["━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('28','29/08','03/09','⼤','Dà Guò','Excès','Compensation','Urgence','Gérer les débordements - gérer l''excès d''énergie','C''est être excessif. Situation où le yang est en excès et passe la mesure. Crise que l''on peut dépasser mais qui peut nous échapper. Agir seul, sans aide extérieure. Opportunité de dépasser les limites habituelles par une créativité hors normes.','["━ ━ ━", "━━━━━", "━━━━━", "━━━━━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('29','04/11-09/11','','坎','Kǎn','Danger','Traversée','Résilience','Ne pas perdre les repères - prudence, patience, persévérance','Apprendre à vivre les épreuves et le danger. Accepter de l''aide. Se relever sans cesse et affronter à nouveau. Situation difficile. Manque de repères. Instabilité. Incertitude. Vertige. Ne pas se laisser entraîner par le vide.','["━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('30','02/05','07/05','离','Lí','Clarté','Illumination','Discernement','Ne pas se laisser éblouir - souplesse, docilité, adaptation','C''est l''éblouissement de la lumière. Danger d''éblouissement. Garder le sens des réalités. Répandre chaleur et clarté. L''attachement doit se faire sans restriction. Accepter et mener à terme une tâche ardue. Nécessité d''y voir clair.','["━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('31','28/11','03/12','咸','Xián','Influence','Séduction','Sensibilité','Gérer l''émotion - humilité et ouverture','C''est inciter à l''action. Générer une dynamique. Enclencher un développement. Ne pas se laisser déstabiliser. Être spontanément réceptif à une influence. Préserver sa marge de manœuvre. Prudence. Respect mutuel.','["━ ━ ━", "━━━━━", "━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('32','11/09','16/09','恒','Héng','Durée','Maintien','Constance','Gérer la constance - action souple adaptée au moment','C''est endurer. Perdurer. Faire dure. Faire face à la réalité quotidienne. Ne pas changer d''attitude. Renouveler ses efforts. Alliance durable. Préserver l''harmonie de l''alliance ou de la situation. Assumer son rôle.','["━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('33','22/11','27/11','遁','Dùn','Retraite','Retrait','Discrétion','Devoir se retirer / action de petite envergure favorable','C''est reculer. Se retirer. Mouvement de retraite pour inverser un rapport de forces momentanément défavorable. Se tenir à l''écart de l''action. Se faire petit. Conserver sa liberté de pensée et d''action.','["━━━━━", "━━━━━", "━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('34','29/07','03/08','⼤','Dà Zhuàng','Puissance','Affirmation','Maîtrise','Gérer la maîtrise de la situation et de la force','C''est maîtriser son énergie. Se fixer un but. Aller de l''avant avec tranquillité et détermination. Manifestation sereine de la puissance. Retenir ce qui est réalisé. Maîtrise de soi.','["━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('35','16/01','20/01','晋','Jn','Progrs','Avance','Assurance','Mettre cartes sur table, formuler, mettre au jour','C''est progresser au grand jour et dans la difficult.','[" ━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('36','05/04','09/04','明','Míng Yí','Obscurité','Dissimulation','Patience','Accepter la mise à mort - accepter les ténèbres','C''est se cacher. Situation d''étouffement. Se désengager d''un conflit dont on n''est pas responsable. Garder secrètes ses intentions. Dissimuler momentanément ses dons et ses possibilités. Entourage hostile.','["━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('37','20/04','25/04','家','Jiā Rén','Famille','Structuration','Bienveillance','Trouver sa place - développer les fonctions de la femme','C''est organiser pour durer. Maintenir ensemble. Connaître sa place et l''occupé. Cohésion avec les membres du clan. L''intérêt particulier passe au second plan. Perspective à long terme. Transformer l''éphémère en durable.','["━━━━━", "━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('38','21/06','26/06','睽','Kuí','Opposition','Réconciliation','Tolérance','Gérer le désaccord interne - succès dans les petites actions','C''est faire face à une divergence. Contradiction qu''il faut rendre féconde. Résoudre les antagonismes. Constater un conflit. Être réaliste. Éviter les malentendus, les contrariétés et les désaccords. Appliquer les règles. Le but est légitime.','["━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('39','22/12','26/12','蹇','Jiǎn','Obstacle','Contournement','Sagesse','Gérer la difficulté extérieure - ne pas affronter le danger','C''est buter sur un obstacle interne ou externe. Quelque chose empêche d''avancer. Cesser momentanément d''agir. Préparer le moment de l''action. S''immobiliser tant que l''obstacle n''aura pas disparu. Reconsidérer la situation.','["━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('40','23/10','28/10','解','Xiè','Libération','Délivrance','Légèreté','Desserrer - S''adapter aux nécessités du moment','C''est dénouer. Se libérer de ce qui pèse et soulager la tension de la situation. Distinguer ce qui est réalisable ou inaccessible. Les forces qui nous retiennent au passé commencent à se libérer. Toutes les difficultés sont épuisées.','["━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('41','27/05','01/06','损','Sǔn','Diminution','Simplification','Détachement','Favoriser ce qui redémarre - ne pas passer à l''action','C''est diminuer. Perte qui permet un rééquilibrage. La situation est au plus bas. Marge de manœuvre réduite. Fin du déclin. Espérance d''un renouveau. Concentration qui entraîne un accroissement de la qualité.','["━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('42','08/03','13/03','益','Yì','Augmentation','Enrichissement','Justesse','Gérer et partager - entreprendre de grandes choses','C''est développer une situation d''expansion qui appelle une réorganisation des priorités internes. Réforme profonde. Action complète. Développement maximal. Période féconde. Nécessité de gérer l''augmentation. Début du déclin.','["━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('43','11/08','16/08','夬','Guài','Percée','Résolution','Fermeté','Ouvrir le passage au souple - agir énergiquement et résolument','C''est résoudre la tension créée par une situation dangereuse. Changer de niveau. Canaliser le débordement. Grande détermination nécessaire. Décision rapide et extrême. Expulser les éléments néfastes. Être ferme et résolu.','["━ ━ ━", "━━━━━", "━━━━━", "━━━━━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('44','23/08','28/08','姤','Gòu','Rencontre','Sélection','Vigilance','Nécessité de s''accorder - attitude souple','C''est accueillir tout ce que l''on ignore ou ce que l''on méconnaît. S''ouvrir à l''énergie Yin. Une collaboration nous est imposée. S''adapter et supporter avec souplesse. Tirer les enseignements pour le futur.','["━━━━━", "━━━━━", "━━━━━", "━━━━━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('45','11/01','15/01','萃','Cuì','Rassemblement','Unification','Conviction','Amasser tous les éléments dont on a besoin - rassembler pour entreprendre','C''est rassembler avec prudence des potentialités fragiles et éparses qui peuvent basculer à tout moment. Situation délicate. Tout ce qui empêche le rassemblement des éléments est néfaste. Se méfier de l''émotivité.','["━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('46','03/10','07/10','升','Shēng','Ascension','Élévation','Persévérance','Sortir de l''ombre pour grandir - accumuler les petites actions','C''est s''enraciner pour s''élever et grandir. Croissance de ce qui va fleurir. Être sans inquiétude. Possibilité d''accéder à des niveaux supérieurs dans tous les domaines. Promotion sociale. Avancer pas à pas.','["━ ━ ━", "━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('47','13/10','17/10','困','Kùn','Oppression','Endurance','Espoir','Relativiser - le retrait est sage','C''est toucher le fond de la situation. Il faut agir pour rompre l''enfermement. On est face à face à soi-même ou à autrui. Forcer la communication. Regarder en soi. Trouver une issue. Renoncer si les moyens font défaut.','["━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('48','23/09','27/09','井','Jng','Puits','Exploration','Profondeur','Aller chercher les solutions dans la profondeur de soi','C''est puiser des nergies au fond de soi-mme.','[" ━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('49','08/05','14/05','⾰','Gé','Révolution','Transformation','Audace','Éliminer ce qui a vieilli - détermination, changement','C''est muter. Changement de pouvoir et pouvoir de changement. Rejeter au bon moment ce qui a vieilli et qui est dépassé. Se révolter. Innover. Fin d''un cycle. Action transformatrice. L''action peut être interne.','["━ ━ ━", "━━━━━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('50','04/09','10/09','⿍','Dǐng','Transformation','Consécration','Noblesse','Établir ce qui est neuf - détermination, droiture','C''est achever. Passage à un niveau supérieur. Transformer ce qui est dépassé. Retour en arrière impossible. La transformation alchimique a lieu. Veiller à la qualité des éléments qui vont constituer la situation.','["━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('51','14/03','19/03','震','Zhèn','Éveilleur','Réaction','Vigilance','Démarrer (lancer toutes les énergies) - le repos n''est pas de mise','C''est ébranler. Donner l''impulsion. Le choc du nouveau qui surprend et peut engendrer une crainte injustifiée. Éviter le feu de paille et l''impulsivité. Possibilité de réagir avec vigueur. Secouer la torpeur.','["━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('52','27/12','31/12','⾉','Gèn','Immobilité','Arrêt','Recueillement','Arrêt avant action - nécessité d''immobilisation','C''est stabiliser. Se calmer le corps et le cœur. Passer à autre chose. Possibilité d''un effondrement imminent.','["━━━━━", "━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('53','16/12','21/12','渐','Jiàn','Développement','Progression graduelle','Patience','Endurance et patience + cadence - progresser pas-à-pas','C''est progresser lentement et régulièrement. Rythme d''apprentissage. Action lente et patiente. Moments de régression. Ne pas se mettre aux commandes de la situation. Situation stable se développant lentement.','["━━━━━", "━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('54','15/06','20/06','归','Guī Mèi','L''epousée','Engagement','Prudence','Choisir les dépendances - prudence et soumission','C''est être dépendant. Moment de trouble se présentant sous la forme d''une union forcée. Prise d''engagements. Risque de décevoir ou d''être déçu. Attention aux promesses non tenues. Réaliser un potentiel caché.','["━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('55','26/04','01/05','丰','Fēng','Abondance','Rayonnement','Conscience','Gérer l''excès de suffisance - régler promptement les problèmes','C''est la profusion. Plénitude qui peut entraver la poursuite du développement. Le résultat est incertain. Gérer et canaliser l''énergie pour maintenir l''abondance. La situation doit être renouvelée constamment.','["━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('56','04/12','09/12','旅','Lǚ','Voyageur','Déplacement','Légèreté','Accepter l''errance - humilité, prudence','C''est être un étranger en territoire inconnu ou hostile. Difficulté de s''intégrer. Pas de soutien amical. Isolement et quête solitaire hors de son réseau habituel. Il faut partir ou se tenir à l''écart.','["━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('57','17/09','22/09','巽','Xùn','Pénétration','Influence subtile','Douceur','Apprivoiser la résistance - favorable pour de petites actions','C''est se modeler. Plier. Accepter en souplesse d''être modelé par la situation. Faire son éducation. Corriger les erreurs. S''adapter. Accepter que la situation évolue différemment de ses prévisions. Faire son éducation. Se développer.','["━━━━━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('58','27/06','01/07','兑','Duì','Plaisir','Serein','Joie','Communiquer dans la joie - échanger, créer la convivialité','C''est échanger. Communiquer dans la joie pour aplanir les différends. Éviter la satisfaction égoïste. Le plaisir doit être partagé.','["━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('59','29/10','03/11','涣','Huàn','Dispersion','Dissipation','Clarté','Séparer le bon grain de l''ivraie - détermination, dissoudre ce qui fait obstacle','C''est dissoudre tout ce qui était bloqué et qui empêchait le passage de l''énergie. Rétablir la fluidité. Disperser tout ce qui bloque la lumière. Dénouer les nœuds à l''origine des problèmes.','["━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('60','02/06','08/06','节','Jié','Limitation','Mesure','Rigueur','Être mesuré - accepter de se donner des limites','C''est être en mesure avec la situation. Savoir se limiter. Trouver le rythme par lequel la vitalité déploie sa juste mesure. Évaluer sa marge de manœuvre. Veiller à demeurer dans les limites pour éviter les troubles qui en découleraient.','["━ ━ ━", "━━━━━", "━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('61','09/06','14/06','中','Zhōng Fú','Vérité intérieure','Confiance','Sincérité','Loyauté - honnêteté avec soi-même - entreprendre, ouverture','C''est harmoniser l''interne et l''externe. Être sans préjugés à sa juste place. Motivation profonde et action juste. Se mettre en accord avec l''ordre cosmique. La conviction intérieure doit être communicative.','["━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('62','10/12','15/12','⼩','Xiǎo Guò','Prudence','Modération','Humilité','Ne pas outrepasser - excessif dans le petit, petit = favorable','C''est être excessif en petit. Incertitude et inconsistance prédominent. Attitude soumise et passive nécessaire. Se maintenir à sa place. Ne pas abandonner ou se révolter. Risque d''éparpirement et de dispersion.','["━ ━ ━", "━ ━ ━", "━━━━━", "━━━━━", "━ ━ ━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('63','14/04','19/04','既','Jì Jì','Accomplissement','Consolidation','Vigilance','Percevoir le chaos à travers l''ordre - petites choses','Tout est en place. L''accomplissement peut être total. Tout élément rajouté amènerait le désordre. Une configuration nouvelle se prépare. Passage de l''ordre au désordre.','["━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;
INSERT INTO hexagrams (numero,date_debut,date_fin,caractere,pinyin,element,strategie,attitude,conseil,synthese,lignes) VALUES ('64','18/10','22/10','未','Wèi Jì','Inachèvement','Poursuite','Ouverture','Trouver les ressources - agir avec prudence','Rien n''est en place. Tout est à faire. L''accomplissement est impossible. Remettre de l''ordre pour entreprendre. Affronter la contestation. Se justifier. Passage du désordre à l''ordre.','["━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━", "━━━━━", "━ ━ ━"]') ON CONFLICT (numero) DO UPDATE SET date_debut=EXCLUDED.date_debut,date_fin=EXCLUDED.date_fin,caractere=EXCLUDED.caractere,pinyin=EXCLUDED.pinyin,element=EXCLUDED.element,strategie=EXCLUDED.strategie,attitude=EXCLUDED.attitude,conseil=EXCLUDED.conseil,synthese=EXCLUDED.synthese,lignes=EXCLUDED.lignes;