CREATE TABLE IF NOT EXISTS hexagrams (
    id SERIAL PRIMARY KEY,
    numero INTEGER NOT NULL UNIQUE,
    date_debut VARCHAR(5) NOT NULL,
    date_fin VARCHAR(5) NOT NULL,
    caractere VARCHAR(1) NOT NULL,
    pinyin VARCHAR(50) NOT NULL,
    element VARCHAR(100),
    strategie VARCHAR(100),
    attitude VARCHAR(100),
    conseil TEXT,
    synthese TEXT,
    lignes TEXT
);
